import numpy as np
import sys

sys.path.append('storage/cognito')

try:
    from adaptive_search_v8 import run_adaptive_search_with_relocation, N_CIRCLES
except ImportError:
    print("Error: Could not import adaptive_search_v8.py.")
    def run_adaptive_search_with_relocation(): return None
    N_CIRCLES = 32

def construct_packing() -> tuple:
    n = N_CIRCLES
    best_params = run_adaptive_search_with_relocation()

    if best_params is not None:
      final_params = best_params.reshape(n, 3)
      final_centers = final_params[:, :2]
      final_radii = final_params[:, 2] * (1.0 - 1e-8)
      return final_centers, final_radii
    else:
      print("Algorithm failed, returning fallback.")
      return np.array([[0.1 + i*0.01, 0.1] for i in range(n)]), np.full(n, 0.001)

